import React, { useEffect, useCallback, useState, useRef } from 'react';
import './panel.css';
import { normalizeUrl } from '../utils/utils';
import DrawingCanvas from './DrawingCanvas';

/**
 * Panel component - listens for P2P messages from phone
 * Handles:
 * - Opening received links in an IFRAME (Remote Browser)
 * - Displaying virtual cursor from phone trackpad
 * - Displaying notes overlay for presenter mode
 * - Simulating keyboard events for presentation control
 * - Toggling fullscreen mode
 * - Rendering drawing annotations
 */
function Panel({ onData }) {
    const [notes, setNotes] = useState('');
    const [browserUrl, setBrowserUrl] = useState('');
    const [cursor, setCursor] = useState({ x: 50, y: 50, active: false });
    const canvasRef = useRef(null);
    const iframeRef = useRef(null);

    // Focus iframe when URL changes to help with keyboard control (Best Effort)
    useEffect(() => {
        if (browserUrl && iframeRef.current) {
            console.log('Focusing Iframe...');
            iframeRef.current.focus();
        }
    }, [browserUrl]);

    /**
     * Simulate a keyboard event
     * @param {string} key - The key to simulate (e.g., 'ArrowRight', 'Escape')
     */
    const simulateKeyPress = useCallback((key) => {
        console.log('Simulating key press:', key);

        // Create and dispatch keyboard events
        const eventOptions = {
            key: key,
            code: key,
            keyCode: getKeyCode(key),
            which: getKeyCode(key),
            bubbles: true,
            cancelable: true
        };

        // Try dispatching to the active element first, then document
        const activeElement = document.activeElement || document.body;

        const keydownEvent = new KeyboardEvent('keydown', eventOptions);
        const keyupEvent = new KeyboardEvent('keyup', eventOptions);

        activeElement.dispatchEvent(keydownEvent);
        activeElement.dispatchEvent(keyupEvent);

        // Also dispatch to document for global handlers
        document.dispatchEvent(new KeyboardEvent('keydown', eventOptions));
        document.dispatchEvent(new KeyboardEvent('keyup', eventOptions));

        // For some websites, we may need to dispatch to window as well
        window.dispatchEvent(new KeyboardEvent('keydown', eventOptions));
        window.dispatchEvent(new KeyboardEvent('keyup', eventOptions));
    }, []);

    /**
     * Toggle fullscreen mode
     */
    const toggleFullscreen = useCallback(() => {
        console.log('Toggling fullscreen');

        if (!document.fullscreenElement) {
            // Enter fullscreen
            const elem = document.documentElement;
            if (elem.requestFullscreen) {
                elem.requestFullscreen();
            } else if (elem.webkitRequestFullscreen) {
                elem.webkitRequestFullscreen();
            } else if (elem.msRequestFullscreen) {
                elem.msRequestFullscreen();
            }
        } else {
            // Exit fullscreen
            if (document.exitFullscreen) {
                document.exitFullscreen();
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            } else if (document.msExitFullscreen) {
                document.msExitFullscreen();
            }
        }
    }, []);

    const handleData = useCallback((data) => {
        // console.log('Received data:', data);

        // Handle link opening - NOW IN IFRAME
        if (data?.type === 'link' && data?.url) {
            const url = normalizeUrl(data.url);
            console.log('Loading URL in Iframe:', url);
            setBrowserUrl(url);
        }

        // Handle Mouse Movements
        if (data?.type === 'mouse') {
            const { dx, dy } = data;
            setCursor(prev => {
                // Calculate new position with clamping (0-100%)
                const sensitivity = 0.15; // Adjustment factor for speed
                let newX = prev.x + (dx * sensitivity);
                let newY = prev.y + (dy * sensitivity);

                newX = Math.max(0, Math.min(100, newX));
                newY = Math.max(0, Math.min(100, newY));

                return {
                    x: newX,
                    y: newY,
                    active: true, // Show cursor when moved
                    lastUpdate: Date.now() // Force re-render if needed
                };
            });
        }

        // Handle notes display
        if (data?.type === 'notes') {
            setNotes(data.text || '');
        }

        // Handle keyboard simulation
        if (data?.type === 'keyboard' && data?.key) {
            simulateKeyPress(data.key);
        }

        // Handle fullscreen toggle
        if (data?.type === 'fullscreen') {
            toggleFullscreen();
        }

        // Handle drawing commands
        if (data?.type === 'draw' && canvasRef.current) {
            const { action, x, y, color, width } = data;

            switch (action) {
                case 'start':
                    canvasRef.current.startPath(x, y, color, width);
                    break;
                case 'move':
                    canvasRef.current.drawPath(x, y);
                    break;
                case 'clear':
                    canvasRef.current.clear();
                    break;
                default:
                    break;
            }
        }
    }, [simulateKeyPress, toggleFullscreen]);

    // Set up data listener
    useEffect(() => {
        onData(handleData);
    }, [onData, handleData]);

    return (
        <div className="panel-container">
            {/* Background or Iframe Browser */}
            {browserUrl ? (
                <iframe
                    ref={iframeRef}
                    src={browserUrl}
                    className="browser-iframe"
                    title="Remote Browser"
                    sandbox="allow-same-origin allow-scripts allow-popups allow-forms"
                />
            ) : (
                <div className="bg-img" />
            )}

            {/* Virtual Cursor */}
            {cursor.active && (
                <div
                    className="virtual-cursor"
                    style={{
                        left: `${cursor.x}%`,
                        top: `${cursor.y}%`
                    }}
                >
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M3 3l7.07 16.97 2.51-7.39 7.39-2.51L3 3z" fill="rgba(0,0,0,0.5)" />
                    </svg>
                </div>
            )}

            {/* Notes Overlay for Presenter Mode */}
            {notes && (
                <div className="notes-overlay">
                    {notes}
                </div>
            )}

            {/* Drawing Canvas Overlay */}
            <DrawingCanvas ref={canvasRef} active={true} />
        </div>
    );
}

/**
 * Get keyCode for common keys
 * @param {string} key - Key name
 * @returns {number} Key code
 */
function getKeyCode(key) {
    const keyCodes = {
        'ArrowLeft': 37,
        'ArrowUp': 38,
        'ArrowRight': 39,
        'ArrowDown': 40,
        'PageUp': 33,
        'PageDown': 34,
        'Home': 36,
        'End': 35,
        'Escape': 27,
        'Enter': 13,
        'Space': 32,
        'Tab': 9,
        'F5': 116,
        'F11': 122,
        'b': 66,
        'B': 66,
        'w': 87,
        'W': 87,
    };
    return keyCodes[key] || key.charCodeAt(0);
}

export default Panel;
